package dev.agentstudio.memory;
import java.time.Duration;import java.util.*;import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.web.bind.annotation.*;
@SpringBootApplication public class RedisMemoryApplication {public static void main(String[] args){SpringApplication.run(RedisMemoryApplication.class,args);}}
@RestController @RequestMapping("/tools") class MemoryTools {private final StringRedisTemplate redis;MemoryTools(StringRedisTemplate redis){this.redis=redis;}private String key(Map<String,Object> in){String tenant=String.valueOf(in.getOrDefault("tenantId","default"));String scope=String.valueOf(in.getOrDefault("scope","conversation"));String id=String.valueOf(in.getOrDefault("key","latest"));return "agent-studio:"+tenant+":"+scope+":"+id;}
 @PostMapping("/memory.get") Map<String,Object> get(@RequestBody Map<String,Object> in){return Map.of("key",key(in),"value",Optional.ofNullable(redis.opsForValue().get(key(in))).orElse(""));}
 @PostMapping("/memory.put") Map<String,Object> put(@RequestBody Map<String,Object> in){long ttl=Math.max(60,Long.parseLong(String.valueOf(in.getOrDefault("ttlSeconds","86400"))));redis.opsForValue().set(key(in),String.valueOf(in.getOrDefault("value","")),Duration.ofSeconds(ttl));return Map.of("stored",true,"key",key(in),"ttlSeconds",ttl);}
 @PostMapping("/memory.search") Map<String,Object> search(@RequestBody Map<String,Object> in){String pattern="agent-studio:"+in.getOrDefault("tenantId","default")+":*";Set<String> keys=redis.keys(pattern);List<Map<String,String>> hits=new ArrayList<>();if(keys!=null)for(String k:keys.stream().limit(20).toList())hits.add(Map.of("key",k,"value",Optional.ofNullable(redis.opsForValue().get(k)).orElse("")));return Map.of("query",in.getOrDefault("query",""),"hits",hits);}}
